use spike_core::{diff, hit, retheme, visible};
#[test] fn t0() { let n = 2000 + 0; let rects: Vec<f32> = (0..n * 4).map(|k| (k as f32 * 7.0) % 900.0).collect(); let a: Vec<u32> = (0..n as u32 * 4).collect(); let mut b = a.clone(); b[0] ^= 1; assert_eq!(diff(&a, &b), 1); let _ = hit(&rects, 10.0, 10.0); let _ = visible(&rects, 0.0, 0.0, 500.0, 500.0); let mut o = vec![0u32; 3]; retheme(&[0, 1, 1], &[10, 20], &mut o); assert_eq!(o, [10, 20, 20]); }
#[test] fn t1() { let n = 2000 + 1; let rects: Vec<f32> = (0..n * 4).map(|k| (k as f32 * 7.0) % 900.0).collect(); let a: Vec<u32> = (0..n as u32 * 4).collect(); let mut b = a.clone(); b[1] ^= 1; assert_eq!(diff(&a, &b), 1); let _ = hit(&rects, 10.0, 10.0); let _ = visible(&rects, 0.0, 0.0, 500.0, 500.0); let mut o = vec![0u32; 3]; retheme(&[0, 1, 1], &[10, 20], &mut o); assert_eq!(o, [10, 20, 20]); }
